components.css:
.ds-acao { display: inline-flex; align-items: center; gap: .6rem; min-height: 48px; padding: 0 1.25rem; background: var(--vermelho, #d93430); color: var(--sobre-vermelho, #ffffff); border: 1.5px solid var(--vermelho, #d93430); border-radius: 0; font: italic 400 1rem/1 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .04em; word-spacing: -.1em; text-decoration: none; cursor: pointer; }
.ds-acao svg { width: 20px; height: 20px; flex: none; }
.ds-acao:focus-visible { outline: 2px solid var(--tinta, #15181b); outline-offset: 3px; }
@media (hover: hover) { .ds-acao:hover { background: var(--vermelho-pressionado, #bb2d29); } }
@media (prefers-reduced-motion: no-preference) { .ds-acao { transition: background-color 150ms ease, transform 120ms cubic-bezier(0.23, 1, 0.32, 1); } .ds-acao:active { transform: scale(.98); } }
@media (prefers-color-scheme: dark) { .ds-acao { border-color: var(--tinta, #eef3f8); } }

.ds-acao-recuada { display: inline-flex; align-items: center; gap: .6rem; min-height: 48px; padding: 0 .875rem; background: var(--papel, #f2f4f3); color: var(--tinta, #15181b); border: 1.5px solid var(--tinta, #15181b); border-radius: 0; font: italic 400 1rem/1 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .04em; word-spacing: -.1em; text-decoration: none; cursor: pointer; }
.ds-acao-recuada svg { width: 20px; height: 20px; flex: none; }
.ds-acao-recuada:focus-visible { outline: 2px solid var(--tinta, #15181b); outline-offset: 3px; }
@media (hover: hover) { .ds-acao-recuada:hover { background: color-mix(in srgb, var(--tinta, #15181b) 8%, var(--papel, #f2f4f3)); } }
@media (prefers-reduced-motion: no-preference) { .ds-acao-recuada { transition: background-color 150ms ease, color 150ms ease, border-color 150ms ease, transform 120ms cubic-bezier(0.23, 1, 0.32, 1); } .ds-acao-recuada:active { transform: scale(.98); } }

.ds-campo { max-width: 32rem; color: var(--tinta, #15181b); font: 400 1.0625rem/1.6 var(--texto, Overpass, system-ui, sans-serif); }
.ds-campo label { display: block; font-size: .9375rem; font-weight: 600; }
.ds-campo input { display: block; width: 100%; min-height: 48px; padding: .5rem 0; background: transparent; color: var(--tinta, #15181b); border: 0; border-bottom: 1.5px solid var(--tinta, #15181b); border-radius: 0; font: 400 1.0625rem/1.5 var(--texto, Overpass, system-ui, sans-serif); }
.ds-campo input::placeholder { color: var(--grafite, #50575e); opacity: 1; }
.ds-campo input:focus-visible { outline: 2px solid var(--tinta, #15181b); outline-offset: 4px; }
.ds-campo-dica { margin: 1rem 0 0; font-size: .9375rem; color: var(--grafite, #50575e); }

.ds-topo { display: flex; align-items: center; justify-content: space-between; gap: 1.5rem; height: 64px; padding: 0 1rem; background: var(--papel, #f2f4f3); color: var(--tinta, #15181b); font: 400 1.0625rem/1.6 var(--texto, Overpass, system-ui, sans-serif); }
.ds-topo a { color: var(--tinta, #15181b); }
.ds-topo a:focus-visible { outline: 2px solid var(--tinta, #15181b); outline-offset: 3px; }
.ds-topo-marca { display: inline-flex; align-items: center; min-height: 44px; font: italic 400 1rem/1 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .04em; word-spacing: -.1em; text-decoration: none; }
.ds-topo nav { display: flex; align-items: center; gap: 1.5rem; }
.ds-topo nav a { display: inline-flex; align-items: center; gap: .5rem; min-height: 44px; font-size: .9375rem; text-decoration: none; }
.ds-topo nav svg { width: 22px; height: 22px; }
@media (hover: hover) { .ds-topo nav a:hover { text-decoration: underline 2px; text-underline-offset: .2em; } }

.ds-folha { position: relative; padding: 12px 12px 12px 28px; background: var(--papel, #f2f4f3); color: var(--tinta, #15181b); }
.ds-folha::after { content: ""; position: absolute; inset: 12px 12px 12px 28px; border: 1.5px solid var(--tinta, #15181b); pointer-events: none; }
.ds-folha-parte { position: relative; padding: 2.5rem 2rem; }
.ds-folha-parte + .ds-folha-parte::before { content: ""; position: absolute; top: 0; left: 1.5px; right: 1.5px; height: 1px; background: var(--grafite, #50575e); }
.ds-folha h2 { margin: 0; font: italic 400 1.5rem/1.1 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .02em; word-spacing: -.18em; }

.ds-carimbo-bloco { display: grid; width: 30rem; max-width: 100%; gap: 1px; background: var(--tinta, #15181b); border: 1.5px solid var(--tinta, #15181b); grid-template-columns: 4.5rem 1fr 1fr 1fr; grid-template-areas: "marca nome nome folha" "marca peca peca cliente" "des des escala unidade" "acao acao acao acao"; color: var(--grafite, #50575e); font: 400 .8125rem/1.3 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .06em; word-spacing: -.1em; }
.ds-carimbo-bloco > :not(.ds-cb-acao) { margin: 0; background: var(--papel, #f2f4f3); }
.ds-cb-marca { grid-area: marca; }
.ds-cb-nome { grid-area: nome; display: flex; align-items: center; padding: 0 .625rem; font-size: 1.125rem; color: var(--tinta, #15181b); }
.ds-cb-campo { display: flex; flex-direction: column; justify-content: center; min-width: 0; padding: .25rem .625rem; }
.ds-cb-campo span:first-child { font-size: .6875rem; line-height: .9; }
.ds-cb-campo span:last-child { color: var(--tinta, #15181b); line-height: 1.05; padding-top: .35em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-cb-mm { text-transform: none; }
.ds-cb-folha { grid-area: folha; } .ds-cb-peca { grid-area: peca; } .ds-cb-cliente { grid-area: cliente; } .ds-cb-des { grid-area: des; } .ds-cb-escala { grid-area: escala; } .ds-cb-unidade { grid-area: unidade; }
.ds-cb-acao { grid-area: acao; display: flex; align-items: center; gap: .6rem; min-height: 48px; padding: 0 .75rem 0 .625rem; background: var(--vermelho, #d93430); color: var(--sobre-vermelho, #ffffff); font: italic 400 1rem/1 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .04em; word-spacing: -.1em; text-decoration: none; white-space: nowrap; }
.ds-cb-acao svg { width: 20px; height: 20px; flex: none; }
.ds-cb-acao svg:last-child { margin-left: auto; }
.ds-cb-acao:focus-visible { outline: 2px solid var(--tinta, #15181b); outline-offset: 3px; }
@media (hover: hover) { .ds-cb-acao:hover { background: var(--vermelho-pressionado, #bb2d29); } }
@media (prefers-reduced-motion: no-preference) { .ds-cb-acao { transition: background-color 150ms ease, color 150ms ease, transform 120ms cubic-bezier(0.23, 1, 0.32, 1); } .ds-cb-acao:active { transform: scale(.98); } }

.ds-carimbo-barra { display: grid; grid-template-columns: auto auto minmax(0, 1fr); align-items: center; gap: .25rem; max-width: 24rem; height: 64px; padding: 0 .5rem; background: var(--papel, #f2f4f3); border-top: 1.5px solid var(--tinta, #15181b); color: var(--grafite, #50575e); font: 400 .8125rem/1.3 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .06em; word-spacing: -.1em; }
.ds-cbar-marca { width: 1.75rem; height: 1.6rem; }
.ds-cbar-campo { display: flex; flex-direction: column; justify-content: center; margin: 0; padding: .25rem .625rem; }
.ds-cbar-campo span:first-child { font-size: .6875rem; line-height: .9; }
.ds-cbar-campo span:last-child { color: var(--tinta, #15181b); line-height: 1.05; padding-top: .35em; }
.ds-cbar-acao { display: inline-flex; align-items: center; gap: .6rem; min-height: 48px; padding: 0 .875rem; background: var(--vermelho, #d93430); color: var(--sobre-vermelho, #ffffff); border: 1.5px solid var(--vermelho, #d93430); font: italic 400 1rem/1 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .04em; word-spacing: -.1em; text-decoration: none; }
.ds-cbar-acao svg { width: 20px; height: 20px; flex: none; }
.ds-cbar-acao:focus-visible { outline: 2px solid var(--tinta, #15181b); outline-offset: 3px; }
@media (hover: hover) { .ds-cbar-acao:hover { background: var(--vermelho-pressionado, #bb2d29); } }
@media (prefers-reduced-motion: no-preference) { .ds-cbar-acao { transition: background-color 150ms ease, transform 120ms cubic-bezier(0.23, 1, 0.32, 1); } .ds-cbar-acao:active { transform: scale(.98); } }
@media (prefers-color-scheme: dark) { .ds-cbar-acao { border-color: var(--tinta, #eef3f8); } }

.ds-cl-rolagem { max-width: 100%; overflow-x: auto; }
.ds-carimbo-linha { display: grid; width: 59rem; height: 3.5rem; gap: 1px; background: var(--tinta, #15181b); border: 1.5px solid var(--tinta, #15181b); grid-template-columns: 2.75rem 9rem 8.75rem 5.5rem 6.75rem 5.5rem 3.75rem 3rem minmax(0, 1fr); color: var(--grafite, #50575e); font: 400 .8125rem/1.3 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .06em; word-spacing: -.1em; }
.ds-carimbo-linha > :not(.ds-cl-acao) { margin: 0; background: var(--papel, #f2f4f3); }
.ds-cl-nome { display: flex; align-items: center; padding: 0 .375rem; font-size: .875rem; color: var(--tinta, #15181b); }
.ds-cl-campo { display: flex; flex-direction: column; justify-content: center; min-width: 0; padding: .25rem .375rem; }
.ds-cl-campo span:first-child { font-size: .6875rem; line-height: .9; }
.ds-cl-campo span:last-child { color: var(--tinta, #15181b); font-size: .75rem; line-height: 1.05; padding-top: .35em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-cl-mm { text-transform: none; }
.ds-cl-acao { display: flex; align-items: center; gap: .6rem; padding: 0 .5rem; background: var(--vermelho, #d93430); color: var(--sobre-vermelho, #ffffff); font: italic 400 1rem/1 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .04em; word-spacing: -.1em; text-decoration: none; white-space: nowrap; }
.ds-cl-acao svg { width: 20px; height: 20px; flex: none; }
.ds-cl-acao:focus-visible { outline: 2px solid var(--tinta, #15181b); outline-offset: 3px; }
@media (hover: hover) { .ds-cl-acao:hover { background: var(--vermelho-pressionado, #bb2d29); } }

.ds-legendas { display: grid; gap: 2rem; max-width: 40rem; color: var(--tinta, #15181b); background: var(--papel, #f2f4f3); font: 400 1.0625rem/1.6 var(--texto, Overpass, system-ui, sans-serif); }
.ds-legenda { margin: 0; }
.ds-legenda figcaption { display: grid; grid-template-columns: 1.65fr 2.55fr; gap: .35rem 1.5rem; padding-top: .375rem; border-top: 1px solid var(--grafite, #50575e); color: var(--grafite, #50575e); font: 400 .8125rem/1.3 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .06em; word-spacing: -.1em; }
.ds-legenda-mm { text-transform: none; }
.ds-vista h3 { margin: 0; padding-top: .375rem; border-top: 1px solid var(--grafite, #50575e); font: italic 400 .9375rem/1.3 var(--letra, osifont, Overpass, sans-serif); text-transform: uppercase; letter-spacing: .06em; word-spacing: -.1em; }
.ds-vista p { margin: .5rem 0 0; }

.ds-linhas { display: block; width: 100%; max-width: 520px; height: auto; background: var(--papel, #f2f4f3); }
.ds-linhas text { font: 400 11px var(--letra, osifont, Overpass, sans-serif); letter-spacing: .06em; fill: var(--grafite, #50575e); }
.ds-linhas .ds-l-cifra { font-size: 13px; letter-spacing: 0; }
.ds-linhas .ds-l-letra { font-size: 13px; letter-spacing: 0; fill: var(--tinta, #15181b); }
.ds-l-vis { stroke: var(--tinta, #15181b); stroke-width: 1.6; stroke-linecap: round; }
.ds-l-oc { stroke: var(--grafite, #50575e); stroke-width: .8; stroke-dasharray: 4 3; }
.ds-l-fina { stroke: var(--grafite, #50575e); stroke-width: .8; }
.ds-l-seta { fill: var(--grafite, #50575e); }
.ds-l-eixo { stroke: var(--grafite, #50575e); stroke-width: .8; stroke-dasharray: 10 3 2 3; }
.ds-l-corte { stroke: var(--tinta, #15181b); stroke-width: .8; stroke-dasharray: 10 3 2 3; }
.ds-l-corte-ponta { stroke: var(--tinta, #15181b); stroke-width: 1.6; fill: none; }
.ds-l-haste { stroke: var(--tinta, #15181b); stroke-width: .8; }
.ds-l-seta-t { fill: var(--tinta, #15181b); }
.ds-l-cons { stroke: var(--construcao, #7fb3dd); stroke-width: 1; stroke-linecap: round; }
.ds-l-cam line { stroke: var(--grafite, #50575e); stroke-width: .5; }
.ds-l-hach { stroke: var(--tinta, #15181b); stroke-width: 1.1; }
.ds-l-secao { stroke: var(--tinta, #15181b); stroke-width: 1.6; }
